import { ContainerBase, Widget, VDOM, ResizeManager, PureContainerBase } from "cx/ui";
import { isNumber, isArray, innerTextTrim, addEventListenerWithOptions } from "cx/util";
import { jsxs, jsx } from "react/jsx-runtime";

class Rect {
	isRect = true;
	l = 0; //left;
	r = 0; //right
	t = 0; //top
	b = 0; //bottom
	constructor(config) {
		Object.assign(this, config);
	}
	width() {
		return this.r - this.l;
	}
	height() {
		return this.b - this.t;
	}
	valid() {
		return this.r > this.l && this.b > this.t;
	}
	makeValid() {
		return new Rect({
			l: Math.min(this.l, this.r),
			r: Math.max(this.l, this.r),
			t: Math.min(this.t, this.b),
			b: Math.max(this.t, this.b),
		});
	}
	isEqual(r) {
		if (!r || !r.isRect) return false;
		return r.l == this.l && r.r == this.r && r.t == this.t && r.b == this.b;
	}
	static add(a, b) {
		return new Rect({
			l: a.l + b.l,
			t: a.t + b.t,
			r: a.r + b.r,
			b: a.b + b.b,
		});
	}
	static multiply(a, b) {
		return new Rect({
			l: a.l + (a.r - a.l) * b.l,
			r: a.l + (a.r - a.l) * b.r,
			t: a.t + (a.b - a.t) * b.t,
			b: a.t + (a.b - a.t) * b.b,
		});
	}
	static margin(r, m) {
		var mr = Rect.convertMargin(m);
		return Rect.add(r, mr);
	}
	static convertMargin(m) {
		if (!m) return new Rect();
		if (m.isRect) return m;
		if (isNumber(m))
			return new Rect({
				l: m,
				t: m,
				r: -m,
				b: -m,
			});
		var mr = Rect.convert(m);
		mr.b = -mr.b;
		mr.r = -mr.r;
		return mr;
	}
	static convert(r) {
		if (!r)
			return new Rect({
				l: 0,
				r: 0,
				t: 0,
				b: 0,
			});
		if (r.isRect) return r;
		if (typeof r === "string") r = r.split(" ");
		if (isArray(r)) {
			return new Rect({
				t: parseFloat(r[0]),
				r: parseFloat(r[1]),
				b: parseFloat(r[2]),
				l: parseFloat(r[3]),
			});
		}
		return new Rect(r);
	}
}

class BoundedObject extends ContainerBase {
	declareData(...args) {
		return super.declareData(
			{
				anchors: undefined,
				offset: undefined,
				margin: undefined,
				padding: undefined,
			},
			...args,
		);
	}
	prepareData(context, instance) {
		super.prepareData(context, instance);
		var { data } = instance;
		data.anchors = Rect.convert(data.anchors);
		data.offset = Rect.convert(data.offset);
		data.margin = Rect.convertMargin(data.margin);
		data.padding = Rect.convertMargin(data.padding);
	}
	calculateBounds(context, instance) {
		var { data } = instance;
		return Rect.add(Rect.add(Rect.multiply(instance.parentRect, data.anchors), data.offset), data.margin);
	}
	prepareBounds(context, instance) {
		var { data } = instance;
		if (
			instance.shouldUpdate ||
			!instance.cached.parentRect ||
			!instance.cached.parentRect.isEqual(context.parentRect) ||
			!data.bounds
		) {
			if (!context.parentRect) throw new Error("Parent bounds were not provided through the context.");
			instance.parentRect = context.parentRect;
			instance.cache("parentRect", context.parentRect);
			instance.markShouldUpdate(context);
			data.bounds = this.calculateBounds(context, instance);
			data.childrenBounds = Rect.add(data.bounds, data.padding);
		}
	}
	prepare(context, instance) {
		this.prepareBounds(context, instance);
		context.push("parentRect", instance.data.childrenBounds);
	}
	prepareCleanup(context, instance) {
		context.pop("parentRect");
	}
}
BoundedObject.prototype.anchors = 0;
BoundedObject.prototype.margin = 0;
BoundedObject.prototype.offset = 0;
BoundedObject.prototype.padding = 0;
BoundedObject.prototype.styled = true;

class Text extends BoundedObject {
	constructor(config) {
		super(config);
	}
	declareData(...args) {
		return super.declareData(...args, {
			value: undefined,
			dx: undefined,
			dy: undefined,
			textAnchor: undefined,
			dominantBaseline: undefined,
			fill: undefined,
			stroke: undefined,
		});
	}
	init() {
		if (this.ta) this.textAnchor = this.ta;
		if (this.db) this.dominantBaseline = this.db;
		if (this.bind) {
			this.value = {
				bind: this.bind,
			};
		} else if (this.tpl) {
			this.value = {
				tpl: this.tpl,
			};
		} else if (this.expr) {
			this.value = {
				expr: this.expr,
			};
		}
		super.init();
	}
	prepare(context, instance) {
		if (this.autoTextAnchor) {
			instance.textAnchor =
				context.textDirection == "right" ? "start" : context.textDirection == "left" ? "end" : this.textAnchor;
			let changed = instance.cache("textAnchor", instance.textAnchor);
			if (changed) instance.markShouldUpdate(context);
		}
		super.prepare(context, instance);
	}
	render(context, instance, key) {
		const { data } = instance;
		const { bounds } = data;
		let textAnchor = this.autoTextAnchor ? instance.textAnchor : data.textAnchor;
		return jsxs(
			"text",
			{
				className: data.classNames,
				x: this.autoTextAnchor && textAnchor == "end" ? bounds.r : bounds.l,
				y: bounds.t,
				dx: data.dx,
				dy: data.dy,
				textAnchor: textAnchor,
				dominantBaseline: data.dominantBaseline,
				style: data.style,
				fill: data.fill,
				stroke: data.stroke,
				children: [data.value, this.renderChildren(context, instance)],
			},
			key,
		);
	}
}
Text.prototype.anchors = "0.5 0.5 0.5 0.5";
Text.prototype.baseClass = "text";
Text.prototype.autoTextAnchor = false;
Widget.alias("svg.text", Text);

class TextualBoundedObject extends BoundedObject {
	constructor(config) {
		super(config);
	}
	add(widget) {
		if (typeof widget != "string") return super.add(...arguments);
		if (this.trimWhitespace) widget = innerTextTrim(widget);
		if (!widget) return;
		return this.add({
			type: Text,
			value: widget,
			textAnchor: "middle",
			dy: "0.4em",
		});
	}
}

class Svg extends BoundedObject {
	constructor(config) {
		super(config);
	}
	initState(context, instance) {
		const size = {
			width: 0,
			height: 0,
		};
		instance.state = {
			size,
		};
	}
	explore(context, instance) {
		context.push("inSvg", true);
		super.explore(context, instance);
	}
	exploreCleanup(context, instance) {
		context.pop("inSvg");
	}
	prepare(context, instance) {
		const size = instance.state.size;
		context.parentRect = new Rect({
			l: 0,
			t: 0,
			r: size.width,
			b: size.height,
		});
		instance.clipRects = {};
		instance.clipRectId = 0;
		context.push("addClipRect", (rect) => {
			const id = `clip-${instance.id}-${++instance.clipRectId}`;
			instance.clipRects[id] = rect;
			return id;
		});
		context.push("inSvg", true);
		super.prepare(context, instance);
	}
	prepareCleanup(context, instance) {
		super.prepareCleanup(context, instance);
		context.pop("addClipRect");
		context.pop("inSvg");
	}
	render(context, instance, key) {
		let eventHandlers = instance.getJsxEventProps();
		if (eventHandlers) {
			delete eventHandlers["onWheelActive"];
		}
		return jsx(
			SvgComponent,
			{
				instance: instance,
				data: instance.data,
				options: context.options,
				size: instance.state.size,
				eventHandlers: eventHandlers,
				children: this.renderChildren(context, instance),
			},
			key,
		);
	}
}
Svg.prototype.anchors = "0 1 1 0";
Svg.prototype.baseClass = "svg";
Svg.prototype.autoWidth = false;
Svg.prototype.autoHeight = false;
Svg.prototype.aspectRatio = 1.618;
function sameSize(a, b) {
	if (!a || !b) return false;
	return a.width == b.width && a.height == b.height;
}
class SvgComponent extends VDOM.Component {
	el;
	offResize;
	offWheelActive;
	render() {
		const { instance, data, size, children, eventHandlers } = this.props;
		const { widget } = instance;
		const defs = [];
		for (const k in instance.clipRects) {
			let cr = instance.clipRects[k];
			defs.push(
				jsx(
					"clipPath",
					{
						id: k,
						children: jsx("rect", {
							x: cr.l,
							y: cr.t,
							width: Math.max(0, cr.width()),
							height: Math.max(0, cr.height()),
						}),
					},
					k,
				),
			);
		}
		let style = data.style;
		if (widget.autoHeight)
			style = {
				...style,
				height: `${size.height}px`,
			};
		if (widget.autoWidth)
			style = {
				...style,
				width: `${size.width}px`,
			};
		//parent div is needed because clientWidth doesn't work on the svg element in FF
		return jsx("div", {
			ref: (el) => {
				this.el = el;
			},
			className: data.classNames,
			style: style,
			...eventHandlers,
			children:
				size.width > 0 &&
				size.height > 0 &&
				jsxs("svg", {
					children: [
						jsx("defs", {
							children: defs,
						}),
						children,
					],
				}),
		});
	}
	onResize() {
		const { instance } = this.props;
		const { widget } = this.props.instance;
		if (!this.el) return;
		let size = {
			width: this.el.clientWidth,
			height: this.el.clientHeight,
		};
		if (widget.autoHeight) size.height = size.width / widget.aspectRatio;
		if (widget.autoWidth) size.width = size.height * widget.aspectRatio;
		if (!sameSize(instance.state.size, size))
			instance.setState({
				size: size,
			});
	}
	componentDidMount() {
		if (!this.el) return;
		this.offResize = ResizeManager.trackElement(this.el, this.onResize.bind(this));
		this.onResize();
		if (this.props.instance.widget.onWheelActive) {
			this.offWheelActive = addEventListenerWithOptions(
				this.el,
				"wheel",
				(event) => {
					const { instance } = this.props;
					instance.invoke("onWheelActive", event, instance);
				},
				{
					passive: false,
				},
			);
		}
	}
	componentDidUpdate() {
		this.onResize();
	}
	componentWillUnmount() {
		this.offResize && this.offResize();
		this.offWheelActive && this.offWheelActive();
	}
}
Widget.alias("svg", Svg);

class Rectangle extends TextualBoundedObject {
	constructor(config) {
		super(config);
	}
	declareData(...args) {
		super.declareData(...args, {
			colorIndex: undefined,
			fill: undefined,
			stroke: undefined,
			rx: undefined,
			ry: undefined,
		});
	}
	render(context, instance, key) {
		const { data } = instance;
		const { bounds, colorIndex } = data;
		if (!bounds.valid()) return false;
		return jsxs(
			"g",
			{
				className: data.classNames,
				children: [
					jsx("rect", {
						className: this.CSS.element(this.baseClass, "rect", colorIndex != null && "color-" + colorIndex),
						x: bounds.l,
						y: bounds.t,
						width: bounds.width(),
						height: bounds.height(),
						style: data.style,
						fill: data.fill,
						stroke: data.stroke,
						rx: data.rx,
						ry: data.ry,
					}),
					this.renderChildren(context, instance),
				],
			},
			key,
		);
	}
}
Rectangle.prototype.baseClass = "rectangle";
Rectangle.prototype.anchors = "0 1 1 0";
Rectangle.prototype.rx = undefined;
Rectangle.prototype.ry = undefined;
Widget.alias("rectangle", Rectangle);

class ClipRect extends BoundedObject {
	constructor(config) {
		super(config);
	}
	prepareBounds(context, instance) {
		super.prepareBounds(context, instance);
		const { data } = instance;
		data.clipId = context.addClipRect(data.bounds);
	}
	render(context, instance, key) {
		const { data } = instance;
		return jsx(
			"g",
			{
				clipPath: `url(#${data.clipId})`,
				children: this.renderChildren(context, instance),
			},
			key,
		);
	}
}
ClipRect.prototype.anchors = "0 1 1 0";

class Ellipse extends TextualBoundedObject {
	constructor(config) {
		super(config);
	}
	declareData(...args) {
		super.declareData(...args, {
			colorIndex: undefined,
			fill: undefined,
			stroke: undefined,
		});
	}
	render(context, instance, key) {
		const { data } = instance;
		const { bounds, colorIndex } = data;
		if (!bounds.valid()) return false;
		return jsxs(
			"g",
			{
				className: data.classNames,
				children: [
					jsx("ellipse", {
						className: this.CSS.element(this.baseClass, "rect", colorIndex != null && "color-" + colorIndex),
						cx: (bounds.l + bounds.r) / 2,
						cy: (bounds.t + bounds.b) / 2,
						rx: bounds.width() / 2,
						ry: bounds.height() / 2,
						style: data.style,
						fill: data.fill,
						stroke: data.stroke,
					}),
					this.renderChildren(context, instance),
				],
			},
			key,
		);
	}
}
Ellipse.prototype.baseClass = "ellipse";
Ellipse.prototype.anchors = "0 1 1 0";
Widget.alias("ellipse", Ellipse);

class Line extends TextualBoundedObject {
	constructor(config) {
		super(config);
	}
	declareData(...args) {
		super.declareData(...args, {
			colorIndex: undefined,
			stroke: undefined,
		});
	}
	render(context, instance, key) {
		const { data, colorIndex } = instance;
		const { bounds } = data;
		return jsxs(
			"g",
			{
				className: data.classNames,
				children: [
					jsx("line", {
						className: this.CSS.element(this.baseClass, "line", colorIndex != null && "color-" + colorIndex),
						x1: bounds.l,
						y1: bounds.t,
						x2: bounds.r,
						y2: bounds.b,
						style: data.style,
						stroke: data.stroke,
					}),
					this.renderChildren(context, instance),
				],
			},
			key,
		);
	}
}
Line.prototype.anchors = "0 1 1 0";
Line.prototype.baseClass = "line";
Widget.alias("line", Line);

class NonOverlappingRect extends BoundedObject {
	constructor(config) {
		super(config);
	}
	prepare(context, instance) {
		super.prepare(context, instance); //calculate bounds
		if (!context.addNonOverlappingBoundingObject)
			throw new Error("Components of type NonOverlappingRect can appear only within a NonOverlappingRectGroup.");
		context.addNonOverlappingBoundingObject(instance);
	}
	render(context, instance, key) {
		if (instance.overlapping) return null;
		return super.render(context, instance, key);
	}
}

class NonOverlappingRectGroup extends PureContainerBase {
	constructor(config) {
		super(config);
	}
	prepare(context, instance) {
		instance.nonOverlappingObjects = [];
		context.push("addNonOverlappingBoundingObject", (objectInstance) => {
			instance.nonOverlappingObjects.push(objectInstance);
		});
	}
	prepareCleanup(context, instance) {
		context.pop("addNonOverlappingBoundingObject");
		instance.nonOverlappingObjects.sort((a, b) => a.data.bounds.r - b.data.bounds.r);
		let visibleObjects = [];
		for (let item of instance.nonOverlappingObjects) {
			let overlapping = false;
			let at = visibleObjects.length - 1;
			while (at >= 0 && visibleObjects[at].data.bounds.r > item.data.bounds.l) {
				let r1 = visibleObjects[at].data.bounds;
				let r2 = item.data.bounds;
				let width = Math.min(r1.r, r2.r) - Math.max(r1.l, r2.l);
				let height = Math.min(r1.b, r2.b) - Math.max(r1.t, r2.t);
				if (width > 0 && height > 0) {
					overlapping = true;
					break;
				}
				at--;
			}
			if (item.overlapping !== overlapping) {
				item.overlapping = overlapping;
				item.markShouldUpdate(context);
			}
			if (!overlapping) visibleObjects.push(item);
		}
	}
}

export {
	BoundedObject,
	ClipRect,
	Ellipse,
	Line,
	NonOverlappingRect,
	NonOverlappingRectGroup,
	Rect,
	Rectangle,
	Svg,
	Text,
	TextualBoundedObject,
};
